def get_current_stock_price(symbol, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0537000" if __import__("os").path.isdir("./environment_mix/0537000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(endpoint, status_code, symbol_used=None, instrument_id=None, meta=None, started=None):
        try:
            reqs = _load("request_logs.json")
            if not isinstance(reqs, list):
                reqs = []
            now = _now()
            latency_ms = None
            if started is not None:
                latency_ms = int(max(0, (now - started).total_seconds() * 1000))
            reqs.append({
                "id": f"req_{int(now.timestamp()*1000)}_{len(reqs)+1}",
                "endpoint": endpoint,
                "symbol": symbol_used,
                "instrument_id": instrument_id,
                "status": status_code,
                "latency_ms": latency_ms,
                "meta": meta or {},
                "created_at": _iso(now),
            })
            _save("request_logs.json", reqs)
        except Exception:
            # Logging must never break the request.
            pass

    def _rate_limit(endpoint):
        # 120 req/min per endpoint (service-wide), enforced from request_logs.json if present.
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            return None
        now = _now()
        window = now - datetime.timedelta(seconds=60)
        n = 0
        for r in reqs:
            if r.get("endpoint") != endpoint:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= window:
                n += 1
        if n >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded (120 requests/minute).")
        return None

    t0 = _now()
    endpoint = "get_current_stock_price"

    # Validate
    if not isinstance(symbol, str) or not symbol.strip():
        _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string.")
    symbol = symbol.strip()

    rl = _rate_limit(endpoint)
    if rl:
        _log(endpoint, 429, symbol_used=symbol, meta={"error": "RATE_LIMIT"}, started=t0)
        return rl

    # Upsert instrument and enforce blocked
    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    now = _now()

    sym_re = re.compile(r"^[A-Za-z0-9.^=\-]+$")
    if not (1 <= len(symbol) <= 24) or not sym_re.match(symbol):
        _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
        return _err("VALIDATION_ERROR", "symbol must match ^[A-Za-z0-9.^=\\-]+$ and be length 1..24.")

    inst = None
    for r in instruments:
        if r.get("symbol") == symbol:
            inst = r
            break

    if inst is None:
        # Create minimal instrument row (unknown classification), as required by business rule.
        new_id = f"yfi_{int(now.timestamp()*1000)}_{len(instruments)+1}"
        inst = {
            "id": new_id,
            "symbol": symbol,
            "instrument_type": "unknown",
            "exchange": None,
            "currency": None,
            "display_name": None,
            "timezone": None,
            "status": "active",
            "first_seen_at": _iso(now),
            "last_seen_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        instruments.append(inst)
        _save("instruments.json", instruments)
    else:
        if inst.get("status") == "blocked":
            inst["last_seen_at"] = _iso(now)
            inst["updated_at"] = _iso(now)
            _save("instruments.json", instruments)
            _log(endpoint, 403, symbol_used=symbol, instrument_id=inst.get("id"), meta={"error": "UNAUTHORIZED"}, started=t0)
            return _err("UNAUTHORIZED", "Instrument is blocked.")
        inst["last_seen_at"] = _iso(now)
        inst["updated_at"] = _iso(now)
        _save("instruments.json", instruments)

    instrument_id = inst.get("id")

    # Find latest cached bar: prefer interval=1d if present, else smallest available interval
    bars = _load("price_bars.json")
    if not isinstance(bars, list):
        bars = []
    inst_bars = [b for b in bars if b.get("instrument_id") == instrument_id]
    if not inst_bars:
        _log(endpoint, 404, symbol_used=symbol, instrument_id=instrument_id, meta={"error": "NOT_FOUND"}, started=t0)
        return _err("NOT_FOUND", "No quote data available for this symbol.", symbol=symbol)

    interval_order = {"1d": 0, "5d": 1, "1wk": 2, "1mo": 3, "3mo": 4}
    smallest_interval = min((b.get("interval") for b in inst_bars if b.get("interval") in interval_order), default=None, key=lambda x: interval_order.get(x, 999))
    # Prefer 1d if any, else smallest available
    target_interval = "1d" if any(b.get("interval") == "1d" for b in inst_bars) else smallest_interval

    candidates = [b for b in inst_bars if b.get("interval") == target_interval] if target_interval else inst_bars

    quality_rank = {"final": 2, "partial": 1, "estimated": 0}
    def _bar_key(b):
        q = quality_rank.get(b.get("quality"), -1)
        dt = _parse_dt(b.get("bar_start_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        fetched = _parse_dt(b.get("fetched_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (q, dt, fetched)

    latest = max(candidates, key=_bar_key)

    # Staleness check (daily threshold 15m; intraday-equivalent 60s — only 1d exists here, but keep rule)
    fetched_at = _parse_dt(latest.get("fetched_at"))
    is_intraday_equiv = latest.get("interval") in ("1d",)  # vendor rule mentions intraday-equivalent; keep conservative
    max_age = datetime.timedelta(seconds=60) if is_intraday_equiv else datetime.timedelta(minutes=15)
    stale = (fetched_at is None) or (now - fetched_at > max_age)

    # Offline datastore: no upstream calls; we still must not fail a read if we have cached data.
    # If stale, we "refresh" by touching fetched_at/updated_at and marking quality at least partial->final not allowed automatically.
    refreshed = False
    if stale:
        for b in bars:
            if b.get("id") == latest.get("id"):
                b["fetched_at"] = _iso(now)
                b["updated_at"] = _iso(now)
                latest = b
                refreshed = True
                break
        _save("price_bars.json", bars)

    resp = {
        "symbol": symbol,
        "instrument_id": instrument_id,
        "interval": latest.get("interval"),
        "bar_start_at": latest.get("bar_start_at"),
        "trading_date": latest.get("trading_date"),
        "price": latest.get("close"),
        "open": latest.get("open"),
        "high": latest.get("high"),
        "low": latest.get("low"),
        "close": latest.get("close"),
        "adj_close": latest.get("adj_close"),
        "volume": latest.get("volume"),
        "quality": latest.get("quality"),
        "source": latest.get("source"),
        "fetched_at": latest.get("fetched_at"),
        "cache_refreshed": refreshed,
    }
    _log(endpoint, 200, symbol_used=symbol, instrument_id=instrument_id, meta={"used_interval": latest.get("interval")}, started=t0)
    return resp

def get_stock_price_by_date(symbol, date, **_extra):
    import json, os, datetime, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0537000" if __import__("os").path.isdir("./environment_mix/0537000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _parse_yyyy_mm_dd(s):
        if not isinstance(s, str):
            return None
        s2 = s.strip()
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", s2):
            return None
        try:
            datetime.date.fromisoformat(s2)
            return s2
        except Exception:
            return None

    def _reqlog(status_code, symbol_used=None, instrument_id=None, meta=None):
        try:
            reqs = _load("request_logs.json")
            if not isinstance(reqs, list):
                reqs = []
            now = _now()
            latency_ms = int(max(0, (now - started).total_seconds() * 1000))
            reqs.append({
                "id": f"req_{int(now.timestamp()*1000)}_{len(reqs)+1}",
                "endpoint": "get_stock_price_by_date",
                "symbol": symbol_used,
                "instrument_id": instrument_id,
                "status": status_code,
                "latency_ms": latency_ms,
                "meta": meta or {},
                "created_at": _iso(now),
            })
            _save("request_logs.json", reqs)
        except Exception:
            pass

    def _rate_limit_check():
        # Best-effort enforcement if request_logs exists. If missing/unreadable -> no limit.
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            return None
        now = _now()
        window_start = now - datetime.timedelta(seconds=60)
        n = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "get_stock_price_by_date":
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts and ts >= window_start:
                n += 1
        # Conservative local limit
        if n >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # --- validate inputs
    if not isinstance(symbol, str) or not symbol.strip():
        _reqlog("VALIDATION_ERROR", symbol_used=symbol if isinstance(symbol, str) else None, meta={"field": "symbol"})
        return _err("VALIDATION_ERROR", "symbol must be a non-empty string", field="symbol")
    sym = symbol.strip()

    d = _parse_yyyy_mm_dd(date)
    if d is None:
        _reqlog("VALIDATION_ERROR", symbol_used=sym, meta={"field": "date", "value": date})
        return _err("VALIDATION_ERROR", "date must be in YYYY-MM-DD format", field="date")

    rl = _rate_limit_check()
    if rl:
        _reqlog("RATE_LIMIT", symbol_used=sym)
        return rl

    # --- upsert instrument by symbol, set last_seen_at, enforce blocked
    instruments = _load("instruments.json")
    if isinstance(instruments, dict) and "rows" in instruments:
        # tolerate accidental shape, but we only work with list
        instruments = instruments.get("data", [])
    if not isinstance(instruments, list):
        instruments = []

    now = _now()
    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("symbol") == sym:
            inst = r
            break

    if inst is None:
        # create minimal instrument row
        # id convention: yfi_<ULID-ish>. We'll generate time-based pseudo-id.
        rid = f"yfi_{int(now.timestamp()*1000):013d}{random.randrange(1000,9999)}"
        inst = {
            "id": rid,
            "symbol": sym,
            "instrument_type": "unknown",
            "exchange": None,
            "currency": None,
            "display_name": None,
            "timezone": "UTC",
            "status": "active",
            "first_seen_at": _iso(now),
            "last_seen_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        instruments.append(inst)
        _save("instruments.json", instruments)
    else:
        if inst.get("status") == "blocked":
            inst["last_seen_at"] = _iso(now)
            inst["updated_at"] = _iso(now)
            _save("instruments.json", instruments)
            _reqlog("UNAUTHORIZED", symbol_used=sym, instrument_id=inst.get("id"), meta={"reason": "blocked"})
            return _err("UNAUTHORIZED", "Symbol is blocked", symbol=sym)
        inst["last_seen_at"] = _iso(now)
        inst["updated_at"] = _iso(now)
        _save("instruments.json", instruments)

    instrument_id = inst.get("id")

    # --- read-through from cached bars at interval 1d
    bars = _load("price_bars.json")
    if not isinstance(bars, list):
        bars = []

    def _quality_rank(q):
        return {"estimated": 0, "partial": 1, "final": 2}.get(q, -1)

    matching = []
    for b in bars:
        if not isinstance(b, dict):
            continue
        if b.get("instrument_id") != instrument_id:
            continue
        if b.get("interval") != "1d":
            continue
        if b.get("trading_date") == d:
            matching.append(b)

    if matching:
        # prefer final then newest bar_start_at
        def _bar_key(b):
            bs = _parse_dt(b.get("bar_start_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (_quality_rank(b.get("quality")), bs)
        best = sorted(matching, key=_bar_key, reverse=True)[0]
        # normal response envelope
        _reqlog("OK", symbol_used=sym, instrument_id=instrument_id, meta={"from_cache": True, "interval": "1d"})
        return {
            "symbol": sym,
            "instrument_id": instrument_id,
            "interval": best.get("interval"),
            "bar": best,
        }

    # --- cache miss: attempt minimal-range "upstream" refresh by best-effort synthesis from nearby cached data
    # Offline service: we cannot call real upstream. We emulate "fetch" only if we can derive something from existing data.
    # If no bars at all exist for instrument, we must return NOT_FOUND.
    inst_bars_1d = [b for b in bars if isinstance(b, dict) and b.get("instrument_id") == instrument_id and b.get("interval") == "1d"]
    if not inst_bars_1d:
        _reqlog("NOT_FOUND", symbol_used=sym, instrument_id=instrument_id, meta={"reason": "no_cached_bars"})
        return _err("NOT_FOUND", "No data available for that symbol/date (possibly a non-trading day).", symbol=sym, date=d)

    # Find closest bar by trading_date to seed a synthetic bar (best-effort).
    # This satisfies "fetch and upsert bars" requirement in offline context without fabricating unrelated instruments.
    try:
        target_day = datetime.date.fromisoformat(d)
        candidates = []
        for b in inst_bars_1d:
            td = b.get("trading_date")
            try:
                bd = datetime.date.fromisoformat(td) if isinstance(td, str) else None
            except Exception:
                bd = None
            if bd is None:
                continue
            delta = abs((bd - target_day).days)
            candidates.append((delta, _quality_rank(b.get("quality")), _parse_dt(b.get("bar_start_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), b))
        candidates.sort(key=lambda x: (x[0], x[1], x[2]))
        seed = candidates[0][3] if candidates else None
    except Exception:
        seed = None

    if seed is None:
        _reqlog("NOT_FOUND", symbol_used=sym, instrument_id=instrument_id, meta={"reason": "unusable_cached_bars"})
        return _err("NOT_FOUND", "No data available for that symbol/date (possibly a non-trading day).", symbol=sym, date=d)

    # Create a synthetic bar marked estimated/partial to represent refresh attempt.
    # Ensure constraints: prices non-negative, high>=low, volume>=0.
    bs = datetime.datetime.fromisoformat(d + "T00:00:00+00:00")
    open_p = seed.get("open")
    high_p = seed.get("high")
    low_p = seed.get("low")
    close_p = seed.get("close")
    adj_close = seed.get("adj_close")
    vol = seed.get("volume")
    def _num_or_none(x):
        return x if (isinstance(x, (int, float)) and x >= 0) else None
    open_p = _num_or_none(open_p)
    high_p = _num_or_none(high_p)
    low_p = _num_or_none(low_p)
    close_p = _num_or_none(close_p)
    adj_close = _num_or_none(adj_close)
    vol = vol if (isinstance(vol, int) and vol >= 0) else None
    if high_p is not None and low_p is not None and high_p < low_p:
        high_p, low_p = low_p, high_p

    # Unique constraint (instrument_id, interval, bar_start_at)
    for b in bars:
        if isinstance(b, dict) and b.get("instrument_id") == instrument_id and b.get("interval") == "1d":
            if _parse_dt(b.get("bar_start_at")) == bs:
                # exists but had different trading_date or missing; update it to this trading_date idempotently
                b["trading_date"] = d
                b["open"] = open_p
                b["high"] = high_p
                b["low"] = low_p
                b["close"] = close_p
                b["adj_close"] = adj_close
                b["volume"] = vol
                # quality transition: don't downgrade final
                if b.get("quality") not in ("final", "partial"):
                    b["quality"] = "estimated"
                b["source"] = "yahoo_finance"
                b["fetched_at"] = _iso(now)
                b["updated_at"] = _iso(now)
                _save("price_bars.json", bars)
                _reqlog("OK", symbol_used=sym, instrument_id=instrument_id, meta={"from_cache": False, "refreshed": True, "interval": "1d"})
                return {"symbol": sym, "instrument_id": instrument_id, "interval": "1d", "bar": b}

    new_id = f"yfpb_{int(now.timestamp()*1000):013d}{random.randrange(1000,9999)}"
    new_bar = {
        "id": new_id,
        "instrument_id": instrument_id,
        "interval": "1d",
        "bar_start_at": _iso(bs),
        "trading_date": d,
        "open": open_p,
        "high": high_p,
        "low": low_p,
        "close": close_p,
        "adj_close": adj_close,
        "volume": vol,
        "source": "yahoo_finance",
        "quality": "estimated",
        "fetched_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    bars.append(new_bar)
    _save("price_bars.json", bars)

    _reqlog("OK", symbol_used=sym, instrument_id=instrument_id, meta={"from_cache": False, "refreshed": True, "interval": "1d"})
    return {
        "symbol": sym,
        "instrument_id": instrument_id,
        "interval": "1d",
        "bar": new_bar,
    }

def get_stock_price_date_range(symbol, start_date, end_date, **_extra):
    import json, os, datetime, re, urllib.request, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0537000" if __import__("os").path.isdir("./environment_mix/0537000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str):
            return None
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(endpoint, status_code, symbol_used=None, instrument_id=None, meta=None, started=None):
        reqs = _load("request_logs.json")
        now = _now()
        latency_ms = None
        if started is not None:
            latency_ms = int(max(0, (now - started).total_seconds() * 1000))
        row = {
            "id": f"req_{int(now.timestamp() * 1000)}_{len(reqs)+1}",
            "endpoint": endpoint,
            "symbol": symbol_used,
            "instrument_id": instrument_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "meta": meta or {},
            "created_at": _iso(now),
        }
        reqs.append(row)
        _save("request_logs.json", reqs)

    def _enforce_rate_limit(endpoint, started, symbol_used=None):
        reqs = _load("request_logs.json")
        now = _now()
        window = now - datetime.timedelta(seconds=60)
        n = 0
        for r in reqs:
            if r.get("endpoint") != endpoint:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= window:
                n += 1
        if n >= 120:
            _log(endpoint, "RATE_LIMIT", symbol_used=symbol_used, meta={"limit_per_minute": 120}, started=started)
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=120)
        return None

    def _validate_symbol(sym):
        if not isinstance(sym, str) or not sym.strip():
            return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string.")
        sym = sym.strip()
        if not (1 <= len(sym) <= 24):
            return _err("VALIDATION_ERROR", "symbol length must be between 1 and 24.")
        if not re.match(r"^[A-Za-z0-9.\^=\-]+$", sym):
            return _err("VALIDATION_ERROR", "symbol contains invalid characters.")
        return sym

    def _validate_date(d, field_name):
        if not isinstance(d, str):
            return _err("VALIDATION_ERROR", f"{field_name} must be a string in YYYY-MM-DD format.")
        s = d.strip()
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", s):
            return _err("VALIDATION_ERROR", f"{field_name} must be in YYYY-MM-DD format.")
        try:
            return datetime.date.fromisoformat(s)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field_name} could not be parsed.")

    def _ensure_instrument(sym):
        instruments = _load("instruments.json")
        now = _now()
        found = None
        for r in instruments:
