    endpoint = "get_stock_price_date_range"
    try:
        sym = _validate_symbol(symbol)
        if isinstance(sym, dict) and sym.get("error"):
            _log(endpoint, "VALIDATION_ERROR", symbol_used=symbol, started=started)
            return sym

        sd = _validate_date(start_date, "start_date")
        if isinstance(sd, dict) and sd.get("error"):
            _log(endpoint, "VALIDATION_ERROR", symbol_used=sym, started=started)
            return sd
        ed = _validate_date(end_date, "end_date")
        if isinstance(ed, dict) and ed.get("error"):
            _log(endpoint, "VALIDATION_ERROR", symbol_used=sym, started=started)
            return ed
        if sd > ed:
            _log(endpoint, "VALIDATION_ERROR", symbol_used=sym, started=started)
            return _err("VALIDATION_ERROR", "start_date must be on or before end_date.")

        rl = _enforce_rate_limit(endpoint, started, symbol_used=sym)
        if rl:
            return rl

        err, ins = _ensure_instrument(sym)
        if err:
            _log(endpoint, err["error"]["code"], symbol_used=sym, started=started)
            return err

        bars = _load("price_bars.json")
        out = []
        sd_s = sd.isoformat()
        ed_s = ed.isoformat()
        for b in bars:
            if b.get("instrument_id") != ins["id"] or b.get("interval") != "1d":
