        if not out:
            chart, e = _fetch_upstream(sym)
            if e:
                _log(endpoint, e["error"]["code"], symbol_used=sym, instrument_id=ins["id"], started=started)
                return e
            _upsert_bars_from_chart(ins["id"], "1d", chart)
            bars = _load("price_bars.json")
            for b in bars:
                if b.get("instrument_id") != ins["id"] or b.get("interval") != "1d":
                    continue
                td = b.get("trading_date")
                if isinstance(td, str) and sd_s <= td <= ed_s:
                    out.append(b)

        if not out:
            _log(endpoint, "NOT_FOUND", symbol_used=sym, instrument_id=ins["id"], started=started)
            return _err("NOT_FOUND", "No data available for that symbol in the requested date range.")

        out.sort(key=lambda b: (b.get("trading_date") or "", b.get("bar_start_at") or ""))

        resp_rows = []
        for b in out:
            resp_rows.append({
                "symbol": sym,
                "instrument_id": ins["id"],
                "interval": b.get("interval"),
                "bar_start_at": b.get("bar_start_at"),
                "trading_date": b.get("trading_date"),
                "open": b.get("open"),
                "high": b.get("high"),
                "low": b.get("low"),
                "close": b.get("close"),
                "adj_close": b.get("adj_close"),
                "volume": b.get("volume"),
                "quality": b.get("quality"),
                "source": b.get("source"),
                "fetched_at": b.get("fetched_at"),
            })

        _log(endpoint, "OK", symbol_used=sym, instrument_id=ins["id"], started=started, meta={"count": len(resp_rows)})
        return {
            "symbol": sym,
            "instrument_id": ins["id"],
            "interval": "1d",
            "start_date": sd_s,
            "end_date": ed_s,
            "count": len(resp_rows),
            "prices": resp_rows,
        }
    except Exception as e:
        _log(endpoint, "UPSTREAM_ERROR", symbol_used=symbol, started=started, meta={"unexpected": str(e)})
        return _err("UPSTREAM_ERROR", "Unexpected failure.", detail=str(e))

def get_historical_stock_prices(symbol, period=None, interval=None, **_extra):
    import json, os, datetime, re, urllib.request, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0537000" if __import__("os").path.isdir("./environment_mix/0537000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(x):
        if x is None:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(x, str):
            return None
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(endpoint, status_code, symbol_used=None, instrument_id=None, meta=None, started=None):
        reqs = _load("request_logs.json")
        now = _now()
        latency_ms = None
        if started is not None:
            latency_ms = int(max(0, (now - started).total_seconds() * 1000))
        row = {
            "id": f"req_{int(now.timestamp() * 1000)}_{len(reqs)+1}",
            "endpoint": endpoint,
            "symbol": symbol_used,
            "instrument_id": instrument_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "meta": meta or {},
            "created_at": _iso(now),
        }
        reqs.append(row)
        _save("request_logs.json", reqs)

    def _enforce_rate_limit(endpoint, started, symbol_used=None):
        reqs = _load("request_logs.json")
        now = _now()
        window = now - datetime.timedelta(seconds=60)
        n = 0
        for r in reqs:
            if r.get("endpoint") != endpoint:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= window:
                n += 1
        if n >= 120:
            _log(endpoint, "RATE_LIMIT", symbol_used=symbol_used, meta={"limit_per_minute": 120}, started=started)
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=120)
        return None

    def _validate_symbol(sym):
        if not isinstance(sym, str) or not sym.strip():
            return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string.")
        sym = sym.strip()
        if not (1 <= len(sym) <= 24):
            return _err("VALIDATION_ERROR", "symbol length must be between 1 and 24.")
        if not re.match(r"^[A-Za-z0-9.\^=\-]+$", sym):
            return _err("VALIDATION_ERROR", "symbol contains invalid characters.")
        return sym

    allowed_periods = {"1d", "5d", "1mo", "3mo", "6mo", "1y", "2y", "5y", "10y", "ytd", "max"}
    allowed_intervals = {"1d", "5d", "1wk", "1mo", "3mo"}

    def _ensure_instrument(sym):
