            return _err("UNAUTHORIZED", "This symbol is blocked."), None
        return None, found

    def _window_start_for(period_str):
        now = _now()
        today = now.date()
        if period_str == "1d":
            return now - datetime.timedelta(days=2)
        if period_str == "5d":
            return now - datetime.timedelta(days=7)
        if period_str == "1mo":
            return now - datetime.timedelta(days=31)
        if period_str == "3mo":
            return now - datetime.timedelta(days=93)
        if period_str == "6mo":
            return now - datetime.timedelta(days=186)
        if period_str == "1y":
            return now - datetime.timedelta(days=366)
        if period_str == "2y":
            return now - datetime.timedelta(days=366 * 2)
        if period_str == "5y":
            return now - datetime.timedelta(days=366 * 5)
        if period_str == "10y":
            return now - datetime.timedelta(days=366 * 10)
        if period_str == "ytd":
            return datetime.datetime(today.year, 1, 1, tzinfo=datetime.timezone.utc)
        if period_str == "max":
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return now - datetime.timedelta(days=31)

    def _fetch_upstream_chart(sym, interval_str, range_str):
        url = "https://query1.finance.yahoo.com/v8/finance/chart/" + urllib.parse.quote(sym)
