    def _upsert_bars_from_chart(instrument_id, interval_str, chart_result):
        bars = _load("price_bars.json")
        now = _now()
        ts = chart_result.get("timestamp") or []
        indicators = (chart_result.get("indicators") or {}).get("quote") or []
        quote0 = indicators[0] if indicators else {}
        adjclose = ((chart_result.get("indicators") or {}).get("adjclose") or [])
        adj0 = adjclose[0] if adjclose else {}

        o = quote0.get("open") or []
        h = quote0.get("high") or []
        l = quote0.get("low") or []
        c = quote0.get("close") or []
        v = quote0.get("volume") or []
        ac = adj0.get("adjclose") or []

        def _at(arr, i):
            return arr[i] if i < len(arr) else None

        for i in range(len(ts)):
            try:
                t = int(ts[i])
            except Exception:
                continue
            bar_start = datetime.datetime.fromtimestamp(t, tz=datetime.timezone.utc)
            trading_date = bar_start.date().isoformat()
            open_ = _at(o, i)
            high_ = _at(h, i)
            low_ = _at(l, i)
            close_ = _at(c, i)
            adj_ = _at(ac, i) if ac else None
            vol_ = _at(v, i)

            if high_ is not None and low_ is not None:
                try:
                    if float(high_) < float(low_):
                        continue
                except Exception:
                    pass

            bar_start_iso = _iso(bar_start)
            existing = None
            for b in bars:
                if b.get("instrument_id") == instrument_id and b.get("interval") == interval_str and b.get("bar_start_at") == bar_start_iso:
                    existing = b
                    break
            if existing is None:
                new_id = f"bar_{int(now.timestamp()*1000)}_{len(bars)+1}_{i}"
                bars.append({
                    "id": new_id,
                    "instrument_id": instrument_id,
                    "interval": interval_str,
                    "bar_start_at": bar_start_iso,
                    "trading_date": trading_date,
                    "open": open_,
                    "high": high_,
                    "low": low_,
                    "close": close_,
                    "adj_close": adj_,
                    "volume": int(vol_) if vol_ is not None else None,
                    "source": "yahoo_finance",
                    "quality": "final",
                    "fetched_at": _iso(now),
                    "created_at": _iso(now),
                    "updated_at": _iso(now),
                })
            else:
                if existing.get("quality") in ("estimated", "partial"):
                    existing["quality"] = "final"
                existing["open"] = open_
                existing["high"] = high_
                existing["low"] = low_
                existing["close"] = close_
                existing["adj_close"] = adj_
                existing["volume"] = int(vol_) if vol_ is not None else None
                existing["source"] = "yahoo_finance"
                existing["fetched_at"] = _iso(now)
                existing["updated_at"] = _iso(now)
        _save("price_bars.json", bars)

    started = _now()
    endpoint = "get_historical_stock_prices"
    try:
        sym = _validate_symbol(symbol)
        if isinstance(sym, dict) and sym.get("error"):
            _log(endpoint, "VALIDATION_ERROR", symbol_used=symbol, started=started)
            return sym

        if period is None:
            period = "1mo"
        if interval is None:
            interval = "1d"

        if not isinstance(period, str) or period not in allowed_periods:
            _log(endpoint, "VALIDATION_ERROR", symbol_used=sym, started=started)
            return _err("VALIDATION_ERROR", "period must be one of the allowed values.", allowed=sorted(allowed_periods))
        if not isinstance(interval, str) or interval not in allowed_intervals:
            _log(endpoint, "VALIDATION_ERROR", symbol_used=sym, started=started)
            return _err("VALIDATION_ERROR", "interval must be one of the allowed values.", allowed=sorted(allowed_intervals))

        rl = _enforce_rate_limit(endpoint, started, symbol_used=sym)
        if rl:
            return rl

        err, ins = _ensure_instrument(sym)
        if err:
            _log(endpoint, err["error"]["code"], symbol_used=sym, started=started)
            return err

        # Serve from cache within computed window; if empty, fetch and upsert then re-read.
        win_start = _window_start_for(period)
        bars = _load("price_bars.json")
        rows = []
        for b in bars:
            if b.get("instrument_id") != ins["id"] or b.get("interval") != interval:
