                bs = _parse_dt(b.get("bar_start_at"))
                if bs and bs >= win_start:
                    rows.append(b)

        if not rows:
            _log(endpoint, "NOT_FOUND", symbol_used=sym, instrument_id=ins["id"], started=started)
            return _err("NOT_FOUND", "No historical series available for this symbol at the requested granularity.")

        rows.sort(key=lambda b: (b.get("bar_start_at") or ""))

        prices = []
        for b in rows:
            prices.append({
                "bar_start_at": b.get("bar_start_at"),
                "trading_date": b.get("trading_date"),
                "open": b.get("open"),
                "high": b.get("high"),
                "low": b.get("low"),
