                "volume": b.get("volume"),
                "quality": b.get("quality"),
                "source": b.get("source"),
                "fetched_at": b.get("fetched_at"),
            })

        _log(endpoint, "OK", symbol_used=sym, instrument_id=ins["id"], started=started, meta={"count": len(prices), "period": period, "interval": interval})
        return {
            "symbol": sym,
            "instrument_id": ins["id"],
            "period": period,
            "interval": interval,
            "count": len(prices),
            "prices": prices,
        }
    except Exception as e:
        _log(endpoint, "UPSTREAM_ERROR", symbol_used=symbol, started=started, meta={"unexpected": str(e)})
        return _err("UPSTREAM_ERROR", "Unexpected failure.", detail=str(e))

def get_dividends(symbol, **_extra):
