        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, instrument_id=None, symbol_val=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + hashlib.sha256(f"{endpoint}|{now}|{random.random()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": endpoint,
            "status": status,
            "symbol": symbol_val,
            "instrument_id": instrument_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if isinstance(extra, dict) and extra:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            # Accept Z or offset; store comparisons in UTC naive.
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s.replace("Z", ""))
        except Exception:
            return None

    def _dt_to_iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return prefix + "_" + hashlib.sha256(f"{prefix}|{now}|{random.random()}".encode("utf-8")).hexdigest()[:24]

    def _upsert_instrument(sym):
        instruments = _load("instruments.json")
        if not isinstance(instruments, list):
            instruments = []
        for r in instruments:
            if isinstance(r, dict) and r.get("symbol") == sym:
                if r.get("status") == "blocked":
                    return None, instruments, _err("UNAUTHORIZED", "Symbol is blocked.")
                r["last_seen_at"] = now
                r["updated_at"] = now
                _save("instruments.json", instruments)
                return r, instruments, None

        # Insert new
        inst = {
            "id": _gen_id("ins"),
            "symbol": sym,
            "instrument_type": "unknown",
            "exchange": None,
            "currency": None,
            "display_name": None,
            "timezone": None,
            "status": "active",
            "first_seen_at": now,
            "last_seen_at": now,
            "created_at": now,
            "updated_at": now,
        }
        instruments.append(inst)
        _save("instruments.json", instruments)
        return inst, instruments, None

    def _validate_symbol(sym):
        if not isinstance(sym, str):
            return _err("VALIDATION_ERROR", "symbol must be a string.")
        sym2 = sym.strip()
        if not sym2:
            return _err("VALIDATION_ERROR", "symbol is required.")
        if not (1 <= len(sym2) <= 24):
            return _err("VALIDATION_ERROR", "symbol length must be between 1 and 24.")
        if re.match(r"^[A-Za-z0-9.^=\-]+$", sym2) is None:
            return _err("VALIDATION_ERROR", "symbol format is invalid.")
        return sym2

    def _simulate_upstream_dividends(sym):
        # Offline server: cannot call upstream. We attempt to derive from existing cache only.
        # Returning None signals upstream failure per tool contract.
        return None

    try:
        sym = _validate_symbol(symbol)
        if isinstance(sym, dict) and "error" in sym:
            _log("get_dividends", "error", symbol_val=symbol)
            return sym

        inst, _, e = _upsert_instrument(sym)
        if e:
            _log("get_dividends", "error", symbol_val=sym)
            return e

        actions = _load("corporate_actions.json")
        if not isinstance(actions, list):
            actions = []

        rows = [
            r for r in actions
            if isinstance(r, dict)
            and r.get("instrument_id") == inst["id"]
            and r.get("action_type") == "dividend"
        ]

        # Determine staleness: if none exist OR newest fetched_at older than 7d -> refresh attempt.
        stale = True
        if rows:
            newest = None
            for r in rows:
                dt = _parse_dt(r.get("fetched_at"))
                if dt and (newest is None or dt > newest):
                    newest = dt
            if newest is not None:
                stale = (datetime.datetime.utcnow() - newest) > datetime.timedelta(days=7)

        if not rows or stale:
            upstream = _simulate_upstream_dividends(sym)
            if upstream is None:
                # If we already have rows, serve them even if stale; otherwise error by contract.
                if not rows:
                    _log("get_dividends", "error", instrument_id=inst["id"], symbol_val=sym, extra={"upstream": "failed"})
                    return _err("UPSTREAM_ERROR", "Upstream corporate-actions query failed.")
            else:
                # Upsert returned events
                # upstream expected list of dicts: {ex_date, pay_date?, amount?, currency?}
                by_key = set()
                for r in actions:
                    if not isinstance(r, dict):
                        continue
                    if r.get("instrument_id") != inst["id"] or r.get("action_type") != "dividend":
                        continue
                    key = (r.get("instrument_id"), r.get("action_type"), r.get("ex_date"),
                           r.get("amount") if r.get("amount") is not None else -1,
                           -1, -1)
                    by_key.add(key)

                changed = False
                for ev in upstream:
                    exd = ev.get("ex_date")
                    if not isinstance(exd, str) or not exd:
                        continue
                    amount = ev.get("amount")
                    if amount is not None:
                        try:
                            amount = float(amount)
                        except Exception:
                            amount = None
                        if amount is not None and amount < 0:
                            amount = None
                    key = (inst["id"], "dividend", exd, amount if amount is not None else -1, -1, -1)
                    if key in by_key:
                        # update fetched_at on matching rows
                        for r in actions:
                            if not isinstance(r, dict):
                                continue
                            if r.get("instrument_id") == inst["id"] and r.get("action_type") == "dividend" and r.get("ex_date") == exd:
                                if ((r.get("amount") if r.get("amount") is not None else -1) == (amount if amount is not None else -1)):
                                    r["fetched_at"] = now
                                    r["updated_at"] = now
                                    changed = True
                        continue

                    row = {
                        "id": _gen_id("ca"),
                        "instrument_id": inst["id"],
                        "action_type": "dividend",
                        "ex_date": exd,
                        "pay_date": ev.get("pay_date") if isinstance(ev.get("pay_date"), str) else None,
                        "amount": amount,
                        "currency": ev.get("currency") if isinstance(ev.get("currency"), str) else None,
                        "split_numerator": None,
                        "split_denominator": None,
                        "source": "yahoo_finance",
                        "fetched_at": now,
                        "created_at": now,
                        "updated_at": now,
                    }
                    actions.append(row)
                    by_key.add(key)
                    changed = True
                if changed:
                    _save("corporate_actions.json", actions)

                rows = [
                    r for r in actions
                    if isinstance(r, dict)
                    and r.get("instrument_id") == inst["id"]
                    and r.get("action_type") == "dividend"
                ]

        if not rows:
            _log("get_dividends", "error", instrument_id=inst["id"], symbol_val=sym)
            return _err("NOT_FOUND", "No dividend history found for symbol.")

        # Sort by ex_date desc (YYYY-MM-DD lexical works)
        rows_sorted = sorted(rows, key=lambda r: (r.get("ex_date") or ""), reverse=True)

        _log("get_dividends", "ok", instrument_id=inst["id"], symbol_val=sym, extra={"count": len(rows_sorted)})
        return {
            "symbol": sym,
            "instrument_id": inst["id"],
            "dividends": rows_sorted,
            "count": len(rows_sorted),
        }
    except Exception as ex:
        _log("get_dividends", "error", symbol_val=symbol, extra={"exception": ex.__class__.__name__})
        return _err("UPSTREAM_ERROR", "Request failed unexpectedly.", detail=str(ex))

