                if r.get("status") == "blocked":
                    return None, _err("UNAUTHORIZED", "Symbol is blocked.")
                r["last_seen_at"] = now
                r["updated_at"] = now
                _save("instruments.json", instruments)
                return r, None
        inst = {
            "id": _gen_id("ins"),
            "symbol": sym,
            "instrument_type": "unknown",
            "exchange": None,
            "currency": None,
            "display_name": None,
            "timezone": None,
            "status": "active",
            "first_seen_at": now,
            "last_seen_at": now,
            "created_at": now,
            "updated_at": now,
        }
        instruments.append(inst)
        _save("instruments.json", instruments)
        return inst, None

    def _simulate_upstream_earning_dates(sym, lim):
        return None

    try:
        sym = _validate_symbol(symbol)
        if isinstance(sym, dict) and "error" in sym:
            _log("get_earning_dates", "error", symbol_val=symbol)
            return sym

        if limit is None:
            limit = 12
        if not isinstance(limit, int):
            _log("get_earning_dates", "error", symbol_val=sym)
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if not (1 <= limit <= 200):
            _log("get_earning_dates", "error", symbol_val=sym)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")

        inst, e = _upsert_instrument(sym)
        if e:
            _log("get_earning_dates", "error", symbol_val=sym)
            return e

        evr = _load("events_and_reports.json")
        if not isinstance(evr, list):
            evr = []

        rows = [
            r for r in evr
            if isinstance(r, dict)
            and r.get("record_type") == "earning_date"
            and r.get("instrument_id") == inst["id"]
        ]

        # stale if newest fetched_at older than 24h OR no rows
        stale = True
        if rows:
            newest = None
            for r in rows:
                dt = _parse_dt(r.get("fetched_at"))
                if dt and (newest is None or dt > newest):
                    newest = dt
            if newest is not None:
                stale = (now_dt - newest) > datetime.timedelta(hours=24)

        if not rows or stale:
            upstream = _simulate_upstream_earning_dates(sym, limit)
            if upstream is None:
                if not rows:
                    _log("get_earning_dates", "error", instrument_id=inst["id"], symbol_val=sym, extra={"upstream": "failed"})
                    return _err("UPSTREAM_ERROR", "Upstream earning-dates query failed.")
            else:
                # upstream expected list: {scheduled_for_date, earnings_time_hint?}
                # Enforce uniqueness: unique(instrument_id, record_type, scheduled_for_date, coalesce(earnings_time_hint,''))
                existing = set()
                for r in evr:
                    if not isinstance(r, dict):
                        continue
                    if r.get("record_type") == "earning_date" and r.get("instrument_id") == inst["id"]:
                        existing.add((r.get("scheduled_for_date"), (r.get("earnings_time_hint") or "")))

                changed = False
                for it in upstream:
                    sfd = it.get("scheduled_for_date")
                    eth = it.get("earnings_time_hint")
                    if not isinstance(sfd, str) or not sfd:
                        continue
                    eth_norm = eth if isinstance(eth, str) else ""
                    key = (sfd, eth_norm)
                    if key in existing:
                        # touch fetched_at
                        for r in evr:
                            if isinstance(r, dict) and r.get("record_type") == "earning_date" and r.get("instrument_id") == inst["id"]:
                                if r.get("scheduled_for_date") == sfd and (r.get("earnings_time_hint") or "") == eth_norm:
                                    r["fetched_at"] = now
                                    r["updated_at"] = now
                                    changed = True
                        continue

                    row = {
                        "id": _gen_id("evr"),
                        "record_type": "earning_date",
                        "instrument_id": inst["id"],
                        "scheduled_for_date": sfd,
                        "earnings_time_hint": eth if isinstance(eth, str) else None,
                        "news_published_at": None,
                        "news_title": None,
                        "news_url": None,
                        "news_source": None,
                        "render_kind": None,
                        "render_params": None,
                        "status": "ready",
                        "result_mime_type": None,
                        "result_base64": None,
                        "result_size_bytes": None,
                        "error_message": None,
                        "source": "yahoo_finance",
                        "fetched_at": now,
                        "expires_at": None,
                        "created_at": now,
                        "updated_at": now,
                    }
                    evr.append(row)
                    existing.add(key)
                    changed = True
                if changed:
                    _save("events_and_reports.json", evr)

                rows = [
                    r for r in evr
                    if isinstance(r, dict)
                    and r.get("record_type") == "earning_date"
                    and r.get("instrument_id") == inst["id"]
                ]

        if not rows:
            _log("get_earning_dates", "error", instrument_id=inst["id"], symbol_val=sym)
            return _err("NOT_FOUND", "No earnings dates available for symbol.")

        # API contract: ordered by scheduled_for_date desc/asc per contract.
        # We'll return most recent first (desc), which fits "recent earnings dates" default.
        rows_sorted = sorted(rows, key=lambda r: (r.get("scheduled_for_date") or ""), reverse=True)[:limit]

        _log("get_earning_dates", "ok", instrument_id=inst["id"], symbol_val=sym, extra={"count": len(rows_sorted), "limit": limit})
        return {
            "symbol": sym,
            "instrument_id": inst["id"],
            "limit": limit,
            "earning_dates": rows_sorted,
            "count": len(rows_sorted),
        }
    except Exception as ex:
        _log("get_earning_dates", "error", symbol_val=symbol, extra={"exception": ex.__class__.__name__})
        return _err("UPSTREAM_ERROR", "Request failed unexpectedly.", detail=str(ex))

def get_news(symbol, **_extra):
    import json, os, datetime, time, re, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0537000" if __import__("os").path.isdir("./environment_mix/0537000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _iso_dt(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix, seed):
        h = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{h}"

    def _log(endpoint, status, latency_ms, meta=None):
        # Schema doesn't declare a request log collection; no-op without inventing files.
        return

    t0 = time.time()
    endpoint = "get_news"

    if not isinstance(symbol, str) or not symbol.strip():
        _log(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
    symbol = symbol.strip()

    # validate symbol format per instruments constraint
    if not (1 <= len(symbol) <= 24) or re.fullmatch(r"^[A-Za-z0-9.\^=\-]+$", symbol) is None:
        _log(endpoint, "error", int((time.time() - t0) * 1000), {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "symbol is invalid")

    instruments = _load("instruments.json")
    events = _load("events_and_reports.json")

    now_iso = _now()
    now_dt = _parse_dt(now_iso)

    # upsert instrument, set last_seen_at
    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("symbol") == symbol:
            inst = r
            break

    if inst is None:
        inst_id = _gen_id("inst", f"{symbol}|{now_iso}")
        inst = {
            "id": inst_id,
            "symbol": symbol,
            "instrument_type": "unknown",
            "exchange": None,
            "currency": None,
            "display_name": None,
            "timezone": None,
            "status": "active",
            "first_seen_at": now_iso,
            "last_seen_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        instruments.append(inst)
        _save("instruments.json", instruments)
    else:
        if inst.get("status") == "blocked":
            inst["last_seen_at"] = now_iso
            inst["updated_at"] = now_iso
            _save("instruments.json", instruments)
            _log(endpoint, "error", int((time.time() - t0) * 1000), {"code": "UNAUTHORIZED"})
            return _err("UNAUTHORIZED", "symbol is blocked")
        inst["last_seen_at"] = now_iso
        inst["updated_at"] = now_iso
        # ensure created_at <= updated_at best-effort
        _save("instruments.json", instruments)

    instrument_id = inst["id"]

    def _news_rows_for_instrument():
        rows = []
        for r in events:
            if not isinstance(r, dict):
                continue
            if r.get("record_type") != "news_item":
                continue
            if r.get("instrument_id") != instrument_id:
                continue
            rows.append(r)
        # order by news_published_at desc
        def key(r):
            dt = _parse_dt(r.get("news_published_at"))
            return dt or datetime.datetime(1970, 1, 1)
        rows.sort(key=key, reverse=True)
        return rows

    news_rows = _news_rows_for_instrument()

    # Refresh policy: stale if fetched_at older than 1h OR none exist.
    stale = True
    if news_rows:
        latest_fetched = None
        for r in news_rows:
            dt = _parse_dt(r.get("fetched_at"))
            if dt and (latest_fetched is None or dt > latest_fetched):
                latest_fetched = dt
        if latest_fetched and now_dt and (now_dt - latest_fetched) <= datetime.timedelta(hours=1):
            stale = False

    # "Read-through fetch on miss": offline server cannot call upstream. If stale/miss, respond NOT_FOUND.
    if stale:
        _log(endpoint, "error", int((time.time() - t0) * 1000), {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "no news feed is available for the symbol")

    # Enforce uniqueness by (instrument_id, record_type, news_url) in-place (best-effort)
    seen = set()
    deduped = []
    for r in news_rows:
        url = r.get("news_url")
        k = (instrument_id, "news_item", url)
        if url and k in seen:
            continue
        if url:
            seen.add(k)
        deduped.append(r)

    _log(endpoint, "ok", int((time.time() - t0) * 1000), {"count": len(deduped)})
    return {
        "symbol": symbol,
        "instrument_id": instrument_id,
        "items": deduped,
    }

def generate_market_dashboard(indices=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64, zlib, struct

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0537000" if __import__("os").path.isdir("./environment_mix/0537000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.utcnow()

    def _now_iso():
        return _now_dt().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix, seed):
        h = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{h}"

    def _png_base64_from_payload(text):
        # Generate a small valid PNG with text embedded into IDAT as uncompressed bytes-like pattern.
        # (Not a real text render; but produces deterministic valid PNG bytes.)
        payload = (text[:2048]).encode("utf-8", "replace")
        # Create a 1xN image where each byte maps to grayscale pixels.
        width = min(256, max(1, len(payload)))
        height = max(1, (len(payload) + width - 1) // width)
        # Build raw image data with filter byte per row (0) + pixels
        raw = bytearray()
        idx = 0
        for _ in range(height):
            raw.append(0)
            row = payload[idx:idx + width]
            idx += width
            if len(row) < width:
                row = row + bytes([0]) * (width - len(row))
            raw.extend(row)
        # PNG with grayscale 8-bit
        def chunk(typ, data):
            crc = zlib.crc32(typ + data) & 0xffffffff
            return struct.pack(">I", len(data)) + typ + data + struct.pack(">I", crc)
        sig = b"\x89PNG\r\n\x1a\n"
        ihdr = struct.pack(">IIBBBBB", width, height, 8, 0, 0, 0, 0)
        idat = zlib.compress(bytes(raw), level=6)
        png = sig + chunk(b"IHDR", ihdr) + chunk(b"IDAT", idat) + chunk(b"IEND", b"")
        return base64.b64encode(png).decode("ascii"), len(png)

    # request log collection not declared; no-op
    t0 = time.time()
    endpoint = "generate_market_dashboard"

    if indices is None:
        indices = "^GSPC,^DJI,^IXIC"
    if not isinstance(indices, str):
        return _err("VALIDATION_ERROR", "indices must be a string")

    parts = [p.strip() for p in indices.split(",") if p.strip()]
    if not (1 <= len(parts) <= 20):
        return _err("VALIDATION_ERROR", "indices must parse to between 1 and 20 symbols")

    # validate symbols
    for s in parts:
        if not (1 <= len(s) <= 24) or re.fullmatch(r"^[A-Za-z0-9.\^=\-]+$", s) is None:
            return _err("VALIDATION_ERROR", f"invalid symbol in indices: {s}")

    instruments = _load("instruments.json")
    events = _load("events_and_reports.json")

    now_iso = _now_iso()
    now_dt = _parse_dt(now_iso)

    # upsert instruments, enforce instrument_type and blocked
    resolved_ids = []
    for sym in parts:
        inst = None
        for r in instruments:
            if isinstance(r, dict) and r.get("symbol") == sym:
                inst = r
                break
        if inst is None:
            inst_id = _gen_id("inst", f"{sym}|{now_iso}")
            inst = {
                "id": inst_id,
                "symbol": sym,
                "instrument_type": "unknown",
                "exchange": None,
                "currency": None,
                "display_name": None,
                "timezone": None,
                "status": "active",
                "first_seen_at": now_iso,
                "last_seen_at": now_iso,
                "created_at": now_iso,
                "updated_at": now_iso,
            }
            instruments.append(inst)
        else:
            if inst.get("status") == "blocked":
                inst["last_seen_at"] = now_iso
                inst["updated_at"] = now_iso
                _save("instruments.json", instruments)
                return _err("UNAUTHORIZED", f"symbol is blocked: {sym}")
            inst["last_seen_at"] = now_iso
            inst["updated_at"] = now_iso

        itype = inst.get("instrument_type") or "unknown"
        if itype not in ("index", "unknown"):
            _save("instruments.json", instruments)
            return _err("VALIDATION_ERROR", f"instrument_type must be index/unknown for dashboard: {sym}")
        resolved_ids.append(inst["id"])

    _save("instruments.json", instruments)

    # expire old cached jobs best-effort
    for r in events:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "render_job":
            continue
        if r.get("status") == "expired":
            continue
        exp = _parse_dt(r.get("expires_at"))
        if exp and now_dt and exp <= now_dt:
            # transition to expired if allowed
            if r.get("status") in ("queued", "running", "ready", "failed"):
                r["status"] = "expired"
                r["updated_at"] = now_iso
                # Do not delete payload, but expired jobs must not return it.
    _save("events_and_reports.json", events)

    # render params normalized
    render_params = {"indices": parts}
    render_kind = "market_dashboard"

    # dedupe: ready and not expired
    cached = None
    for r in events:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "render_job":
            continue
        if r.get("render_kind") != render_kind:
            continue
        if r.get("render_params") != render_params:
            continue
        if r.get("status") != "ready":
            continue
        exp = _parse_dt(r.get("expires_at"))
        if exp and now_dt and exp > now_dt:
            cached = r
            break

    if cached:
        # expired jobs must not return payload (already checked exp)
        if cached.get("result_mime_type") != "image/png" or not cached.get("result_base64"):
            return _err("CONFLICT", "cached render job is invalid")
        return {
            "job": cached,
            "mime_type": cached.get("result_mime_type"),
            "image_base64": cached.get("result_base64"),
        }

    # create new job and run synchronously queued->running->ready/failed
    job_id = _gen_id("rjob", f"{render_kind}|{json.dumps(render_params, sort_keys=True)}|{now_iso}")
    expires_at = (_now_dt() + datetime.timedelta(hours=24)).replace(microsecond=0).isoformat() + "Z"

    job = {
        "id": job_id,
        "record_type": "render_job",
        "instrument_id": None,
        "scheduled_for_date": None,
        "earnings_time_hint": None,
        "news_published_at": None,
        "news_title": None,
        "news_url": None,
        "news_source": None,
        "render_kind": render_kind,
        "render_params": render_params,
        "status": "queued",
        "result_mime_type": None,
        "result_base64": None,
        "result_size_bytes": None,
        "error_message": None,
        "source": "renderer",
        "fetched_at": None,
        "expires_at": expires_at,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    events.append(job)
    _save("events_and_reports.json", events)

    # transition queued->running
    job["status"] = "running"
    job["updated_at"] = _now_iso()
    _save("events_and_reports.json", events)

    # "Upstream data retrieval" cannot happen offline; render from available inputs.
    try:
        text = f"{render_kind}|" + ",".join(parts) + "|" + job["updated_at"]
        b64, size_bytes = _png_base64_from_payload(text)
    except Exception:
        # transition running->failed
        job["status"] = "failed"
        job["error_message"] = "render failed"
        job["updated_at"] = _now_iso()
        _save("events_and_reports.json", events)
        return _err("UPSTREAM_ERROR", "required market data could not be retrieved to render the dashboard")

    if size_bytes > 10485760:
        job["status"] = "failed"
        job["error_message"] = "result too large"
        job["updated_at"] = _now_iso()
        _save("events_and_reports.json", events)
        return _err("CONFLICT", "render result exceeds size limit")

    # transition running->ready and store result
    job["status"] = "ready"
    job["result_mime_type"] = "image/png"
    job["result_base64"] = b64
    job["result_size_bytes"] = int(size_bytes)
    job["error_message"] = None
    job["updated_at"] = _now_iso()
    _save("events_and_reports.json", events)

    return {"job": job, "mime_type": "image/png", "image_base64": b64}

