                inst["last_seen_at"] = now_iso
                inst["updated_at"] = now_iso
                _save("instruments.json", instruments)
                return _err("UNAUTHORIZED", f"symbol is blocked: {sym}")
            inst["last_seen_at"] = now_iso
            inst["updated_at"] = now_iso
        resolved.append(inst)

    _save("instruments.json", instruments)

    # Determine if "none can be resolved to market data": require at least one cached bar for any instrument.
    inst_ids = {r["id"] for r in resolved if isinstance(r, dict) and r.get("id")}
    has_any_market_data = False
    for b in price_bars:
        if not isinstance(b, dict):
            continue
        if b.get("instrument_id") in inst_ids:
            has_any_market_data = True
            break

    if not has_any_market_data:
        return _err("NOT_FOUND", "none of the requested symbols can be resolved to market data")

    # expire old jobs best-effort
    for r in events:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "render_job":
            continue
        if r.get("status") == "expired":
            continue
        exp = _parse_dt(r.get("expires_at"))
        if exp and now_dt and exp <= now_dt:
            if r.get("status") in ("queued", "running", "ready", "failed"):
                r["status"] = "expired"
                r["updated_at"] = now_iso
    _save("events_and_reports.json", events)

    render_kind = "portfolio_report"
    render_params = {"symbols": parts}

    # dedupe cached ready, not expired
    cached = None
    for r in events:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "render_job":
            continue
        if r.get("render_kind") != render_kind:
            continue
        if r.get("render_params") != render_params:
            continue
        if r.get("status") != "ready":
            continue
        exp = _parse_dt(r.get("expires_at"))
        if exp and now_dt and exp > now_dt:
            cached = r
            break

    if cached:
        if cached.get("result_mime_type") != "image/png" or not cached.get("result_base64"):
            return _err("CONFLICT", "cached render job is invalid")
        return {"job": cached, "mime_type": "image/png", "image_base64": cached.get("result_base64")}

    job_id = _gen_id("rjob", f"{render_kind}|{json.dumps(render_params, sort_keys=True)}|{now_iso}")
    expires_at = (_now_dt() + datetime.timedelta(hours=24)).replace(microsecond=0).isoformat() + "Z"

    job = {
        "id": job_id,
        "record_type": "render_job",
        "instrument_id": None,
        "scheduled_for_date": None,
        "earnings_time_hint": None,
        "news_published_at": None,
        "news_title": None,
        "news_url": None,
        "news_source": None,
        "render_kind": render_kind,
        "render_params": render_params,
        "status": "queued",
        "result_mime_type": None,
        "result_base64": None,
        "result_size_bytes": None,
        "error_message": None,
        "source": "renderer",
        "fetched_at": None,
        "expires_at": expires_at,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    events.append(job)
    _save("events_and_reports.json", events)

    # queued->running
    job["status"] = "running"
    job["updated_at"] = _now_iso()
    _save("events_and_reports.json", events)

    # offline rendering, but must fail if required data not present: we already checked at least one bar.
    try:
        text = f"{render_kind}|" + ",".join(parts) + "|" + job["updated_at"]
        b64, size_bytes = _png_base64_from_payload(text)
    except Exception:
        job["status"] = "failed"
        job["error_message"] = "render failed"
        job["updated_at"] = _now_iso()
        _save("events_and_reports.json", events)
        return _err("UPSTREAM_ERROR", "required historical/quote data could not be retrieved to render the report")

    if size_bytes > 10485760:
        job["status"] = "failed"
        job["error_message"] = "result too large"
        job["updated_at"] = _now_iso()
        _save("events_and_reports.json", events)
        return _err("CONFLICT", "render result exceeds size limit")

    job["status"] = "ready"
    job["result_mime_type"] = "image/png"
    job["result_base64"] = b64
    job["result_size_bytes"] = int(size_bytes)
    job["error_message"] = None
    job["updated_at"] = _now_iso()
    _save("events_and_reports.json", events)

    return {"job": job, "mime_type": "image/png", "image_base64": b64}

def generate_stock_technical_analysis(symbol=None, **_extra):
    import json, os, datetime, time, re, hashlib, base64, zlib, struct

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0537000" if __import__("os").path.isdir("./environment_mix/0537000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.utcnow()

    def _now_iso():
        return _now_dt().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix, seed):
        h = hashlib.sha256(seed.encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{h}"

    def _png_base64_from_payload(text):
        payload = (text[:4096]).encode("utf-8", "replace")
        width = min(256, max(1, len(payload)))
        height = max(1, (len(payload) + width - 1) // width)
        raw = bytearray()
        idx = 0
        for _ in range(height):
            raw.append(0)
            row = payload[idx:idx + width]
            idx += width
            if len(row) < width:
                row = row + bytes([0]) * (width - len(row))
            raw.extend(row)

        def chunk(typ, data):
            crc = zlib.crc32(typ + data) & 0xffffffff
            return struct.pack(">I", len(data)) + typ + data + struct.pack(">I", crc)

        sig = b"\x89PNG\r\n\x1a\n"
        ihdr = struct.pack(">IIBBBBB", width, height, 8, 0, 0, 0, 0)
        idat = zlib.compress(bytes(raw), level=6)
        png = sig + chunk(b"IHDR", ihdr) + chunk(b"IDAT", idat) + chunk(b"IEND", b"")
        return base64.b64encode(png).decode("ascii"), len(png)

    # Auth is ambient and there are no credential params; accept unless store indicates no permitted context.
    # Since schema provides no auth/quota collections, enforce QUOTA_EXCEEDED via render_job count per day best-effort.
    if symbol is None:
        symbol = "TSLA"
    if not isinstance(symbol, str) or not symbol.strip():
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string")
    symbol = symbol.strip()

    if not (1 <= len(symbol) <= 24) or re.fullmatch(r"^[A-Za-z0-9.\^=\-]+$", symbol) is None:
        return _err("VALIDATION_ERROR", "symbol is invalid")

    instruments = _load("instruments.json")
    events = _load("events_and_reports.json")

    now_iso = _now_iso()
    now_dt = _parse_dt(now_iso)

    # Quota: max 50 technical analysis generations per UTC day (best-effort; no schema counters exist)
    day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day)
    used = 0
    for r in events:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "render_job":
            continue
        if r.get("render_kind") != "stock_technical_analysis":
            continue
        created = _parse_dt(r.get("created_at"))
        if created and created >= day_start:
            used += 1
    if used >= 50:
        return _err("QUOTA_EXCEEDED", "daily report generation limit exceeded")

    # upsert instrument; reject if blocked
    inst = None
    for r in instruments:
        if isinstance(r, dict) and r.get("symbol") == symbol:
            inst = r
            break

    if inst is None:
        inst_id = _gen_id("inst", f"{symbol}|{now_iso}")
        inst = {
            "id": inst_id,
            "symbol": symbol,
            "instrument_type": "unknown",
            "exchange": None,
            "currency": None,
            "display_name": None,
            "timezone": None,
            "status": "active",
            "first_seen_at": now_iso,
            "last_seen_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        instruments.append(inst)
        _save("instruments.json", instruments)
    else:
        if inst.get("status") == "blocked":
            inst["last_seen_at"] = now_iso
            inst["updated_at"] = now_iso
            _save("instruments.json", instruments)
            return _err("UNAUTHORIZED", "symbol is blocked")
        inst["last_seen_at"] = now_iso
        inst["updated_at"] = now_iso
        _save("instruments.json", instruments)

    instrument_id = inst["id"]

    # expire old jobs best-effort
    for r in events:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "render_job":
            continue
        if r.get("status") == "expired":
            continue
        exp = _parse_dt(r.get("expires_at"))
        if exp and now_dt and exp <= now_dt:
            if r.get("status") in ("queued", "running", "ready", "failed"):
                r["status"] = "expired"
                r["updated_at"] = now_iso
    _save("events_and_reports.json", events)

    render_kind = "stock_technical_analysis"
    render_params = {"symbol": symbol}

    # dedupe ready and not expired (instrument-specific)
    cached = None
    for r in events:
        if not isinstance(r, dict):
            continue
        if r.get("record_type") != "render_job":
            continue
        if r.get("render_kind") != render_kind:
            continue
        if r.get("instrument_id") != instrument_id:
            continue
        if r.get("render_params") != render_params:
            continue
        if r.get("status") != "ready":
            continue
        exp = _parse_dt(r.get("expires_at"))
        if exp and now_dt and exp > now_dt:
            cached = r
            break

    if cached:
        # expired jobs must not return result_base64; exp checked.
        return {"job": cached}

    # create job, then transition through states (simulate async by completing in same call)
    job_id = _gen_id("rjob", f"{render_kind}|{instrument_id}|{json.dumps(render_params, sort_keys=True)}|{now_iso}")
    expires_at = (_now_dt() + datetime.timedelta(hours=24)).replace(microsecond=0).isoformat() + "Z"

    job = {
        "id": job_id,
        "record_type": "render_job",
        "instrument_id": instrument_id,
        "scheduled_for_date": None,
        "earnings_time_hint": None,
        "news_published_at": None,
        "news_title": None,
        "news_url": None,
        "news_source": None,
        "render_kind": render_kind,
        "render_params": render_params,
        "status": "queued",
        "result_mime_type": None,
        "result_base64": None,
        "result_size_bytes": None,
        "error_message": None,
        "source": "renderer",
        "fetched_at": None,
        "expires_at": expires_at,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    events.append(job)
    _save("events_and_reports.json", events)

    # queued->running
    job["status"] = "running"
    job["updated_at"] = _now_iso()
    _save("events_and_reports.json", events)

    # Render now (offline); if fails, mark failed
    try:
        text = f"{render_kind}|{symbol}|{job['updated_at']}"
        b64, size_bytes = _png_base64_from_payload(text)
    except Exception:
        job["status"] = "failed"
        job["error_message"] = "render failed"
        job["updated_at"] = _now_iso()
        _save("events_and_reports.json", events)
        return {"job": job}

    if size_bytes > 10485760:
        job["status"] = "failed"
        job["error_message"] = "result too large"
        job["updated_at"] = _now_iso()
        _save("events_and_reports.json", events)
        return {"job": job}

    # running->ready with required fields
    job["status"] = "ready"
    job["result_mime_type"] = "image/png"
    job["result_base64"] = b64
    job["result_size_bytes"] = int(size_bytes)
    job["error_message"] = None
    job["updated_at"] = _now_iso()
    _save("events_and_reports.json", events)

    return {"job": job}

def list_instruments(query=None, status=None, instrument_type=None, exchange=None, currency=None, page=None, page_size=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0537000" if __import__("os").path.isdir("./environment_mix/0537000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc).isoformat()

    # Validation
    if query is not None and not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in {"active", "inactive", "delisted", "blocked"}:
            return _err("VALIDATION_ERROR", "Invalid status", allowed=["active", "inactive", "delisted", "blocked"])
    if instrument_type is not None:
        if not isinstance(instrument_type, str):
            return _err("VALIDATION_ERROR", "instrument_type must be a string")
        # Tool's enum includes values not present in schema; accept only schema-supported types.
        # Map common aliases to schema values.
        mapping = {
            "mutual_fund": "fund",
            "fx": "forex",
        }
        it = mapping.get(instrument_type, instrument_type)
        if it not in {"equity", "etf", "index", "fund", "forex", "crypto", "unknown"}:
            return _err(
                "VALIDATION_ERROR",
                "Invalid instrument_type for this service",
                allowed=["equity", "etf", "index", "fund", "forex", "crypto", "unknown"],
            )
        instrument_type = it
    if exchange is not None and not isinstance(exchange, str):
        return _err("VALIDATION_ERROR", "exchange must be a string")
    if currency is not None and not isinstance(currency, str):
        return _err("VALIDATION_ERROR", "currency must be a string")
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")

    instruments = _load("instruments.json")

    q = (query or "").strip().lower()
    rows = []
    for r in instruments:
        if status is not None and r.get("status") != status:
            continue
        if instrument_type is not None and r.get("instrument_type") != instrument_type:
            continue
        if exchange is not None and (r.get("exchange") or None) != exchange:
            continue
        if currency is not None and (r.get("currency") or None) != currency:
            continue
        if q:
            sym = (r.get("symbol") or "").lower()
            dn = (r.get("display_name") or "").lower()
            if q not in sym and q not in dn:
                continue
        rows.append(r)

    def _dt_key(x):
        # last_seen_at may be null; order nulls last.
        v = x.get("last_seen_at")
        if not v:
            return (0, "")
        return (1, v)

    rows.sort(key=lambda x: (_dt_key(x), (x.get("symbol") or "").upper()), reverse=True)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    # Optional cursor for convenience: next page number as a string
    next_cursor = str(page + 1) if has_more else None

    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        },
    }

