def update_instrument(id, display_name=None, instrument_type=None, exchange=None, currency=None, timezone=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0537000" if __import__("os").path.isdir("./environment_mix/0537000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now = now_dt.isoformat()

    if id is None or not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    # Validate fields
    if display_name is not None and not isinstance(display_name, str):
        return _err("VALIDATION_ERROR", "display_name must be a string")
    if exchange is not None and not isinstance(exchange, str):
        return _err("VALIDATION_ERROR", "exchange must be a string")
    if currency is not None and not isinstance(currency, str):
        return _err("VALIDATION_ERROR", "currency must be a string")
    if timezone is not None and not isinstance(timezone, str):
        return _err("VALIDATION_ERROR", "timezone must be a string")

    if instrument_type is not None:
        if not isinstance(instrument_type, str):
            return _err("VALIDATION_ERROR", "instrument_type must be a string")
        mapping = {
            "mutual_fund": "fund",
            "fx": "forex",
        }
        it = mapping.get(instrument_type, instrument_type)
        if it not in {"equity", "etf", "index", "fund", "forex", "crypto", "unknown"}:
            return _err(
                "VALIDATION_ERROR",
                "Invalid instrument_type for this service",
                allowed=["equity", "etf", "index", "fund", "forex", "crypto", "unknown"],
            )
        instrument_type = it

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in {"active", "inactive", "delisted", "blocked"}:
            return _err("VALIDATION_ERROR", "Invalid status", allowed=["active", "inactive", "delisted", "blocked"])

    instruments = _load("instruments.json")
    idx = None
    for i, r in enumerate(instruments):
        if r.get("id") == id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Instrument not found", id=id)

    row = instruments[idx]

    # Enforce lifecycle transitions
    transitions = {
        "active": {"inactive", "delisted", "blocked"},
        "inactive": {"active", "blocked", "delisted"},
        "delisted": {"blocked"},
        "blocked": {"active", "inactive"},
    }
    if status is not None:
        cur = row.get("status")
        if cur not in transitions:
            return _err("VALIDATION_ERROR", "Instrument has invalid current status", current_status=cur)
        if status != cur and status not in transitions[cur]:
            return _err(
                "INVALID_TRANSITION",
                "Invalid status transition",
                from_status=cur,
                to_status=status,
                allowed=sorted(list(transitions[cur])),
            )

    # Apply updates (only mutable fields per tool)
    changed = False
    for k, v in [
        ("display_name", display_name),
        ("instrument_type", instrument_type),
        ("exchange", exchange),
        ("currency", currency),
        ("timezone", timezone),
        ("status", status),
    ]:
        if v is not None and row.get(k) != v:
            row[k] = v
            changed = True

    if not changed:
        # Idempotent: still update updated_at to reflect write? Real services often do.
        # We'll avoid "no success without effect" by treating as no-op but successful only if it actually changes.
        return _err("CONFLICT", "No changes to apply")

    # Audit timestamps
    row["updated_at"] = now

    # created_at <= updated_at (best-effort)
    ca = row.get("created_at")
    if isinstance(ca, str) and ca > row["updated_at"]:
        row["created_at"] = row["updated_at"]

    instruments[idx] = row
    _save("instruments.json", instruments)

    return {
        "data": row,
        "meta": {"latency_ms": int((time.time() - t0) * 1000), "timestamp": now},
    }

