        if status not in {"queued", "running", "ready", "failed", "expired"}:
            return _err("VALIDATION_ERROR", "Invalid status")
    if instrument_id is not None and not isinstance(instrument_id, str):
        return _err("VALIDATION_ERROR", "instrument_id must be a string")
    if include_expired is None:
        include_expired = False
    if not isinstance(include_expired, bool):
        return _err("VALIDATION_ERROR", "include_expired must be a boolean")
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")

    # Load and sweep expiration (observable dynamics)
    events = _load("events_and_reports.json")
    changed = False
    for r in events:
        if r.get("record_type") != "render_job":
            continue
        if r.get("status") == "expired":
            continue
        exp = r.get("expires_at")
        if exp:
            try:
                exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00"))
                if exp_dt <= now_dt:
                    # transition to expired if allowed
                    cur = r.get("status")
                    if cur in {"queued", "running", "ready", "failed"}:
                        r["status"] = "expired"
                        r["updated_at"] = now
                        # expired jobs must not return payload
                        r["result_base64"] = None
                        r["result_mime_type"] = None
                        r["result_size_bytes"] = None
                        changed = True
            except ValueError:
                # ignore malformed expires_at; do not crash
                pass
    if changed:
        _save("events_and_reports.json", events)

    rows = []
    for r in events:
        if r.get("record_type") != "render_job":
            continue
        if r.get("render_kind") is None:
            continue
        if not include_expired and r.get("status") == "expired":
            continue
        if render_kind is not None and r.get("render_kind") != render_kind:
            continue
        if status is not None and r.get("status") != status:
            continue
        if instrument_id is not None and (r.get("instrument_id") or None) != instrument_id:
            continue
        rows.append(r)

    rows.sort(key=lambda x: (x.get("created_at") or "", x.get("id") or ""), reverse=True)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total
    next_cursor = str(page + 1) if has_more else None

    return {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        },
    }

def get_render_job(id, include_result=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0537000" if __import__("os").path.isdir("./environment_mix/0537000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = datetime.datetime.now(datetime.timezone.utc)

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_request_logs_file():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])

    def _reqlog(status_code, job_id=None, meta=None):
        _ensure_request_logs_file()
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        now = _now()
        latency_ms = int(max(0, (now - started).total_seconds() * 1000))
        reqs.append({
            "id": f"req_{int(now.timestamp()*1000)}_{len(reqs)+1}",
            "endpoint": "get_render_job",
            "status": status_code,
            "latency_ms": latency_ms,
            "meta": {"job_id": job_id, **(meta or {})},
            "created_at": _iso(now),
        })
        _save("request_logs.json", reqs)

    def _rate_limit_check():
        # Conservative default: 120 req/min per datastore
        _ensure_request_logs_file()
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        now = _now()
        window_start = now - datetime.timedelta(seconds=60)
        count = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "get_render_job":
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt is None:
                continue
            if dt >= window_start and dt <= now:
                count += 1
        if count >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        e = _err("VALIDATION_ERROR", "Invalid id", id=id)
        _reqlog(400, job_id=id, meta={"error": e["error"]["code"]})
        return e
    id = id.strip()

    if include_result is None:
        include_result = False
    if not isinstance(include_result, bool):
        e = _err("VALIDATION_ERROR", "include_result must be a boolean", include_result=include_result)
        _reqlog(400, job_id=id, meta={"error": e["error"]["code"]})
        return e

    rl = _rate_limit_check()
    if rl:
        _reqlog(429, job_id=id, meta={"error": rl["error"]["code"]})
        return rl

    # Load data
    rows = _load("events_and_reports.json")
    if isinstance(rows, dict) and "rows" in rows and isinstance(rows["rows"], list):
        rows = rows["rows"]
    if not isinstance(rows, list):
        rows = []

    job = None
    for r in rows:
        if isinstance(r, dict) and r.get("id") == id:
            job = r
            break

    if not job:
        e = _err("NOT_FOUND", "Render job not found", id=id)
        _reqlog(404, job_id=id, meta={"error": e["error"]["code"]})
        return e

    if job.get("record_type") != "render_job":
        e = _err("NOT_FOUND", "Render job not found", id=id)
        _reqlog(404, job_id=id, meta={"error": e["error"]["code"]})
        return e

    now = _now()

    # Expiration evaluation (retention rule)
    expires_at = _parse_dt(job.get("expires_at"))
    is_expired = False
    if expires_at is not None and expires_at <= now:
        is_expired = True

    # If include_result requested but job is expired, it's a validation error per tool contract
    if include_result and is_expired:
        e = _err("VALIDATION_ERROR", "Render job is expired; content is not available", id=id)
        _reqlog(400, job_id=id, meta={"error": e["error"]["code"]})
        return e

    # Build response, omitting result by default
    out = dict(job)

    # Never return result_base64 for expired jobs
    if is_expired:
        out.pop("result_base64", None)

    if not include_result:
        # Metadata-only: omit potentially large content regardless of status
        out.pop("result_base64", None)
        # Keep mime type as metadata if present; contract says include both only when requested.
        # So for metadata-only, remove result_mime_type too to match "metadata only".
        out.pop("result_mime_type", None)

    else:
        # include_result=True
        if out.get("status") == "ready" and not is_expired:
            # Enforce contract: must be image/png when ready and has content
            # If stored row is inconsistent, do not crash; just omit content.
            if out.get("result_mime_type") != "image/png" or not out.get("result_base64"):
                out.pop("result_base64", None)
                out.pop("result_mime_type", None)
        else:
            out.pop("result_base64", None)
            out.pop("result_mime_type", None)

    resp = {
        "render_job": out
    }
    _reqlog(200, job_id=id, meta={"include_result": include_result})
    return resp

def refresh_symbol_cache(symbol, domain, period=None, interval=None, freq=None, limit=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0537000" if __import__("os").path.isdir("./environment_mix/0537000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _parse_date(s):
        if not isinstance(s, str):
            return None
        try:
            return datetime.date.fromisoformat(s)
        except ValueError:
            return None

    def _gen_id(prefix):
        # Keep stable-ish vendor-like prefixes
        return f"{prefix}_{int(time.time()*1000)}_{random.randint(1000,9999)}"

    def _log(endpoint, status_code, symbol_used=None, instrument_id=None, meta=None, started=None):
        try:
            reqs = _load("request_logs.json")
            if not isinstance(reqs, list):
                reqs = []
            now = _now()
            latency_ms = None
            if started is not None:
                latency_ms = int(max(0, (now - started).total_seconds() * 1000))
            reqs.append({
                "id": f"req_{int(now.timestamp()*1000)}_{len(reqs)+1}",
                "endpoint": endpoint,
                "symbol": symbol_used,
                "instrument_id": instrument_id,
                "status": status_code,
                "latency_ms": latency_ms,
                "meta": meta or {},
                "created_at": _iso(now),
            })
            _save("request_logs.json", reqs)
        except Exception:
            pass

    def _rate_limit(endpoint):
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            return None
        now = _now()
        window = now - datetime.timedelta(seconds=60)
        n = 0
        for r in reqs:
            if r.get("endpoint") != endpoint:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= window:
                n += 1
        if n >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded (60 refresh requests/minute).")
        return None

    t0 = _now()
    endpoint = "refresh_symbol_cache"

    # Validate base params
    if not isinstance(symbol, str) or not symbol.strip():
        _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
        return _err("VALIDATION_ERROR", "symbol is required and must be a non-empty string.")
    symbol = symbol.strip()

    if not isinstance(domain, str) or domain not in {"quote", "prices", "dividends", "fundamentals_income", "fundamentals_cashflow", "earnings_dates", "news"}:
        _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
        return _err("VALIDATION_ERROR", "domain must be one of: quote, prices, dividends, fundamentals_income, fundamentals_cashflow, earnings_dates, news.")

    # IMPORTANT: Do NOT reject extra params when domain doesn't use them (audit defect).
    # Only enforce required ones for the chosen domain and validate types if provided.

    if period is not None and (not isinstance(period, str) or period not in {"1d","5d","1mo","3mo","6mo","1y","2y","5y","10y","ytd","max"}):
        _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
        return _err("VALIDATION_ERROR", "period must be one of {1d,5d,1mo,3mo,6mo,1y,2y,5y,10y,ytd,max} when provided.")
    if interval is not None and (not isinstance(interval, str) or interval not in {"1d","5d","1wk","1mo","3mo"}):
        _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
        return _err("VALIDATION_ERROR", "interval must be one of {1d,5d,1wk,1mo,3mo} when provided.")
    if freq is not None and (not isinstance(freq, str) or freq not in {"yearly","quarterly","trainling"}):
        _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
        return _err("VALIDATION_ERROR", "freq must be one of {yearly,quarterly,trainling} when provided.")
    if limit is not None:
        if not isinstance(limit, int):
            _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
            return _err("VALIDATION_ERROR", "limit must be an integer when provided.")
        if limit < 1 or limit > 200:
            _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200 when provided.")

    # Enforce domain-specific required params
    if domain == "prices" and period is None:
        _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
        return _err("VALIDATION_ERROR", "period is required when domain=prices (business rule).")
    if domain == "prices" and interval is None:
        interval = "1d"
    if domain in {"fundamentals_income", "fundamentals_cashflow"} and freq is None:
        _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
        return _err("VALIDATION_ERROR", "freq is required when refreshing fundamentals (business rule).")
    if domain == "earnings_dates" and limit is None:
        limit = 25  # safe default

    rl = _rate_limit(endpoint)
    if rl:
        _log(endpoint, 429, symbol_used=symbol, meta={"error": "RATE_LIMIT"}, started=t0)
        return rl

    # Upsert instrument + blocked check
    sym_re = re.compile(r"^[A-Za-z0-9.^=\-]+$")
    if not (1 <= len(symbol) <= 24) or not sym_re.match(symbol):
        _log(endpoint, 400, symbol_used=symbol, meta={"error": "VALIDATION_ERROR"}, started=t0)
        return _err("VALIDATION_ERROR", "symbol must match ^[A-Za-z0-9.^=\\-]+$ and be length 1..24.")

    instruments = _load("instruments.json")
    if not isinstance(instruments, list):
        instruments = []
    now = _now()

    inst = None
    for r in instruments:
        if r.get("symbol") == symbol:
            inst = r
            break
    if inst is None:
        inst_id = f"yfi_{int(now.timestamp()*1000)}_{len(instruments)+1}"
        inst = {
            "id": inst_id,
            "symbol": symbol,
            "instrument_type": "unknown",
            "exchange": None,
            "currency": None,
            "display_name": None,
            "timezone": None,
            "status": "active",
            "first_seen_at": _iso(now),
            "last_seen_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        instruments.append(inst)
    else:
        inst["last_seen_at"] = _iso(now)
        inst["updated_at"] = _iso(now)

    if inst.get("status") == "blocked":
        _save("instruments.json", instruments)
        _log(endpoint, 403, symbol_used=symbol, instrument_id=inst.get("id"), meta={"error": "UNAUTHORIZED"}, started=t0)
        return _err("UNAUTHORIZED", "Instrument is blocked.")

    _save("instruments.json", instruments)
    instrument_id = inst.get("id")

    # Offline "refresh": we mark fetched_at/updated_at and upsert minimal rows only when necessary.
    summary = {"domain": domain, "instrument_id": instrument_id, "symbol": symbol}

    if domain in {"quote", "prices"}:
        bars = _load("price_bars.json")
        if not isinstance(bars, list):
            bars = []

        # Touch the latest bar for interval, or create one if none exists to ensure "no success without effect".
        target_interval = interval if domain == "prices" else "1d"
        inst_bars = [b for b in bars if b.get("instrument_id") == instrument_id and b.get("interval") == target_interval]

        changed = 0
        if inst_bars:
            # Touch all in the requested window? Minimal: touch most recent bar.
            def _parse_bar_dt(b):
                return _parse_dt(b.get("bar_start_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)
            latest = max(inst_bars, key=_parse_bar_dt)
            for b in bars:
                if b.get("id") == latest.get("id"):
                    b["fetched_at"] = _iso(now)
                    b["updated_at"] = _iso(now)
                    changed = 1
                    break
        else:
            # Create a placeholder bar at today's date with null prices (allowed by schema)
            bar_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
            trading_date = bar_start.date().isoformat()
            new_row = {
                "id": _gen_id("yfpb"),
                "instrument_id": instrument_id,
                "interval": target_interval,
                "bar_start_at": _iso(bar_start),
                "trading_date": trading_date,
                "open": None,
                "high": None,
                "low": None,
                "close": None,
                "adj_close": None,
                "volume": None,
                "source": "yahoo_finance",
                "quality": "estimated",
                "fetched_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            # enforce uniqueness best-effort
            exists = any(
                b.get("instrument_id") == instrument_id and b.get("interval") == target_interval and b.get("bar_start_at") == new_row["bar_start_at"]
                for b in bars
            )
            if not exists:
                bars.append(new_row)
                changed = 1

        if changed == 0:
            _log(endpoint, 404, symbol_used=symbol, instrument_id=instrument_id, meta={"error": "NOT_FOUND", "reason": "no_rows_to_refresh"}, started=t0)
            return _err("NOT_FOUND", "No cached price rows exist to refresh and no new row could be created.")
        _save("price_bars.json", bars)
        summary.update({"refreshed_records": changed, "interval": target_interval})

    elif domain == "dividends":
        actions = _load("corporate_actions.json")
        if not isinstance(actions, list):
            actions = []
        inst_actions = [a for a in actions if a.get("instrument_id") == instrument_id and a.get("action_type") == "dividend"]
        changed = 0
        if inst_actions:
            # touch newest
            def _k(a):
                return a.get("ex_date") or ""
            latest = max(inst_actions, key=_k)
            for a in actions:
                if a.get("id") == latest.get("id"):
                    a["fetched_at"] = _iso(now)
                    a["updated_at"] = _iso(now)
                    changed = 1
                    break
        else:
            # create a minimal dividend record with null amount (allowed)
            ex_date = now.date().isoformat()
            new_row = {
                "id": _gen_id("yfca"),
                "instrument_id": instrument_id,
                "action_type": "dividend",
                "ex_date": ex_date,
                "pay_date": None,
                "amount": None,
                "currency": None,
                "split_numerator": None,
                "split_denominator": None,
                "source": "yahoo_finance",
                "fetched_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            # uniqueness best-effort for schema constraint with amount null
            exists = any(
                a.get("instrument_id") == instrument_id and a.get("action_type") == "dividend" and a.get("ex_date") == ex_date and a.get("amount") is None
                for a in actions
            )
            if not exists:
                actions.append(new_row)
                changed = 1
        if changed == 0:
            _log(endpoint, 404, symbol_used=symbol, instrument_id=instrument_id, meta={"error": "NOT_FOUND"}, started=t0)
            return _err("NOT_FOUND", "No corporate action rows exist to refresh and no new row could be created.")
        _save("corporate_actions.json", actions)
        summary.update({"refreshed_records": changed})

    elif domain in {"fundamentals_income", "fundamentals_cashflow"}:
        fnds = _load("fundamentals.json")
        if not isinstance(fnds, list):
            fnds = []
        stmt = "income_statement" if domain == "fundamentals_income" else "cashflow"
        subset = [r for r in fnds if r.get("instrument_id") == instrument_id and r.get("statement_type") == stmt and r.get("frequency") == freq]
        changed = 0
        if subset:
            # touch newest by period_end_date
            latest = max(subset, key=lambda r: r.get("period_end_date") or "")
            for r in fnds:
                if r.get("id") == latest.get("id"):
                    r["fetched_at"] = _iso(now)
                    r["updated_at"] = _iso(now)
                    changed = 1
                    break
        else:
            # create minimal non-empty data object (required)
            ped = now.date().isoformat()
            new_row = {
                "id": _gen_id("yffn"),
                "instrument_id": instrument_id,
                "statement_type": stmt,
                "frequency": freq,
                "period_end_date": ped,
                "currency": None,
                "data": {"refreshed_at": _iso(now)},
                "source": "yahoo_finance",
                "fetched_at": _iso(now),
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            exists = any(
                r.get("instrument_id") == instrument_id and r.get("statement_type") == stmt and r.get("frequency") == freq and r.get("period_end_date") == ped
                for r in fnds
            )
            if not exists:
                fnds.append(new_row)
                changed = 1
        if changed == 0:
            _log(endpoint, 404, symbol_used=symbol, instrument_id=instrument_id, meta={"error": "NOT_FOUND"}, started=t0)
            return _err("NOT_FOUND", "No fundamentals rows exist to refresh and no new row could be created.")
        _save("fundamentals.json", fnds)
        summary.update({"refreshed_records": changed, "statement_type": stmt, "frequency": freq})

    elif domain == "earnings_dates":
        evs = _load("events_and_reports.json")
        if not isinstance(evs, list):
            evs = []
        subset = [r for r in evs if r.get("record_type") == "earning_date" and r.get("instrument_id") == instrument_id]
        changed = 0
        if subset:
            latest = max(subset, key=lambda r: r.get("scheduled_for_date") or "")
            for r in evs:
                if r.get("id") == latest.get("id"):
                    r["fetched_at"] = _iso(now)
                    r["updated_at"] = _iso(now)
                    changed = 1
                    break
        else:
            # Create one earnings_date row; must be status ready and have scheduled_for_date + instrument_id
            sched = (now.date() + datetime.timedelta(days=30)).isoformat()
            new_row = {
                "id": _gen_id("yfer"),
                "record_type": "earning_date",
                "instrument_id": instrument_id,
                "scheduled_for_date": sched,
                "earnings_time_hint": None,
                "news_published_at": None,
                "news_title": None,
                "news_url": None,
                "news_source": None,
                "render_kind": None,
                "render_params": None,
                "status": "ready",
                "result_mime_type": None,
                "result_base64": None,
                "result_size_bytes": None,
                "error_message": None,
                "source": "yahoo_finance",
                "fetched_at": _iso(now),
                "expires_at": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            # uniqueness: instrument_id, record_type, scheduled_for_date, earnings_time_hint (coalesce '')
            exists = any(
                r.get("record_type") == "earning_date" and r.get("instrument_id") == instrument_id and r.get("scheduled_for_date") == sched and (r.get("earnings_time_hint") or "") == ""
                for r in evs
            )
            if not exists:
                evs.append(new_row)
                changed = 1
        if changed == 0:
            _log(endpoint, 404, symbol_used=symbol, instrument_id=instrument_id, meta={"error": "NOT_FOUND"}, started=t0)
            return _err("NOT_FOUND", "No earnings_date rows exist to refresh and no new row could be created.")
        _save("events_and_reports.json", evs)
        summary.update({"refreshed_records": changed, "limit": limit})

    elif domain == "news":
        evs = _load("events_and_reports.json")
        if not isinstance(evs, list):
            evs = []
        subset = [r for r in evs if r.get("record_type") == "news_item" and r.get("instrument_id") == instrument_id]
        changed = 0
        if subset:
            latest = max(subset, key=lambda r: _parse_dt(r.get("news_published_at")) or datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc))
            for r in evs:
                if r.get("id") == latest.get("id"):
                    r["fetched_at"] = _iso(now)
                    r["updated_at"] = _iso(now)
                    changed = 1
                    break
        else:
            # Create one news_item row; must have instrument_id, news_title, news_url; status ready.
            url = f"https://finance.yahoo.com/news/cache-refresh-{symbol}-{int(now.timestamp())}.html"
            new_row = {
                "id": _gen_id("yfer"),
                "record_type": "news_item",
                "instrument_id": instrument_id,
                "scheduled_for_date": None,
                "earnings_time_hint": None,
                "news_published_at": _iso(now),
                "news_title": f"Cache refresh placeholder for {symbol}",
                "news_url": url,
                "news_source": "yahoo_finance",
                "render_kind": None,
                "render_params": None,
                "status": "ready",
                "result_mime_type": None,
                "result_base64": None,
                "result_size_bytes": None,
                "error_message": None,
                "source": "yahoo_finance",
                "fetched_at": _iso(now),
                "expires_at": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            # uniqueness: instrument_id, record_type, news_url
            exists = any(
                r.get("record_type") == "news_item" and r.get("instrument_id") == instrument_id and r.get("news_url") == url
                for r in evs
            )
            if not exists:
                evs.append(new_row)
                changed = 1
        if changed == 0:
            _log(endpoint, 404, symbol_used=symbol, instrument_id=instrument_id, meta={"error": "NOT_FOUND"}, started=t0)
            return _err("NOT_FOUND", "No news rows exist to refresh and no new row could be created.")
        _save("events_and_reports.json", evs)
        summary.update({"refreshed_records": changed})

    _log(endpoint, 200, symbol_used=symbol, instrument_id=instrument_id, meta={"domain": domain}, started=t0)
    return summary
